const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',chart:'M3 3v18h18 M6 15l4-5 4 3 6-8',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',database:'M20 5c0 2-4 3-8 3s-8-1-8-3 4-3 8-3 8 1 8 3z M4 5v14c0 2 4 3 8 3s8-1 8-3V5 M4 12c0 2 4 3 8 3s8-1 8-3',help:'M12 17h.01 M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',sun:'M12 3v-1 M12 22v-1 M3 12H2 M22 12h-1 M5 5l-1-1 M20 20l-1-1 M5 19l-1 1 M20 4l-1 1 M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0',moon:'M21 13a9 9 0 0 1-10-10A9 9 0 1 0 21 13',plus:'M12 5v14 M5 12h14',arrow:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',clock:'M12 8v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',flag:'M5 21V3 M5 3c5-4 9 4 14 0v10c-5 4-9-4-14 0',target:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0 M12 12h.01',bolt:'M13 2L4 14h7l-1 8 10-13h-8z',edit:'M15 4l5 5 M4 20l5-1L21 7l-4-4L5 15z',x:'M6 6l12 12 M6 18L18 6',check:'M5 12l4 4L19 6',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
const icon = n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.chart}"/></svg>`;
const brandMark=()=>{const p=[['#cfd8e3',4,0],['#cfd8e3',5,0],['#cfd8e3',6,0],['#9ec345',3,1],['#e2993d',4,1],['#f2922e',5,1],['#f07236',6,1],['#ef5442',7,1],['#86c64e',2,2],['#e14f59',8,2],['#54b881',1,3],['currentColor',6,3],['#995da8',9,3],['#43aeab',1,4],['currentColor',6,4],['#746fc3',9,4],['#64b6f6',1,5],['currentColor',5,5],['#4a7ee4',9,5],['#67b9f4',1,6],['#ffd166',5,6],['#4a81f0',9,6],['#64b6f6',1,7],['#3886fb',9,7],['#67b9f4',2,8],['#4a81f0',8,8],['#67b9f4',3,9],['#64b6f6',4,9],['#62b6ff',5,9],['#4a81f0',6,9],['#3883f9',7,9]];return `<svg viewBox="0 0 35 37" shape-rendering="crispEdges" aria-hidden="true" focusable="false">${p.map(([c,x,y])=>`<rect x="${1+x*3}" y="${2+y*3}" width="3" height="3" fill="${c}"/>`).join('')}</svg>`};
const KEY='elite-marathon.v1';
let data, storageError='', recoveryRaw=null;
try { const raw=localStorage.getItem(KEY); if(raw){try{data=validateData(JSON.parse(raw));}catch{recoveryRaw=raw;storageError='旧数据无法读取；请在数据管理下载备份后恢复保存';}} }
catch{storageError='浏览器不允许本地保存，请导出备份';}
if(!recoveryRaw)try{data=recoverWorkspace(localStorage)||data;}catch(e){storageError='恢复未完成：'+e.message;}
if(!recoveryRaw)try{data=importLondonSplits(localStorage,data);}catch(e){storageError='分段导入未完成：'+e.message;}
if(!data)data={version:1,races:[{id:uid(),name:'新赛事',date:localDate(),demo:false,athletes:[]}]};
let theme='dark';try{theme=localStorage.getItem('elite-marathon.theme')||'dark';}catch{}
document.documentElement.dataset.theme=theme==='light'?'light':'dark';
function syncThemeColor(){const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.content=document.documentElement.dataset.theme==='light'?'#f4f7fc':'#090c11';}
syncThemeColor();
let raceId=data.races[0].id, athleteId=data.races[0].athletes[0]?.id, page='overview', mode='pace', checkpoint=Math.max(0,POINTS.indexOf(Math.max(0,...data.races[0].athletes.flatMap(a=>a.splits.map(s=>s.distance))))), division='men', hidden=new Set(), toastTimer, chartScope='top', chartWidth=0, playbackFrame, modalOpener, storageNoticeDismissed=false;
try{const state=JSON.parse(sessionStorage.getItem('elite-marathon.view')||'null');if(state&&data.races.some(r=>r.id===state.raceId)){raceId=state.raceId;athleteId=state.athleteId;if(['overview','splits','data','help'].includes(state.page))page=state.page;if(['men','women','open'].includes(state.division))division=state.division;if(['pace','gap','lead'].includes(state.mode))mode=state.mode;if(Number.isInteger(state.checkpoint)&&state.checkpoint>=0&&state.checkpoint<10)checkpoint=state.checkpoint;}}catch{}
function saveView(){try{sessionStorage.setItem('elite-marathon.view',JSON.stringify({raceId,athleteId,page,mode,checkpoint,division}));}catch{}}
const chartObserver=new ResizeObserver(entries=>{const width=Math.floor(entries[0].contentRect.width)-24;if(width>0&&Math.abs(width-chartWidth)>1){chartWidth=width;refreshChart();}});
function refreshChart(){const region=$('#chart-region');if(!region)return;const focus=focusSelector(document.activeElement);region.innerHTML=chartMarkup();bindChart();restoreFocus(focus);}
function updatePlayback(){playbackFrame=null;if(page!=='overview')return;const focus=focusSelector(document.activeElement),template=document.createElement('template');template.innerHTML=overview();for(const selector of ['.stats','#chart-region','.left-stack>section:last-child','.right-stack']){$(selector)?.replaceWith(template.content.querySelector(selector));}$('.checkpoint-top').innerHTML=template.content.querySelector('.checkpoint-top').innerHTML;$('#checkpoint').setAttribute('aria-valuetext',label(POINTS[checkpoint]));bindOverview();chartObserver.disconnect();chartObserver.observe($('#chart-region'));saveView();restoreFocus(focus);}
const race=()=>data.races.find(r=>r.id===raceId)||data.races[0];
const divisions=()=>['men','women','open'].filter(g=>groupAthletes(race().athletes,g).length);
const visibleAthletes=()=>groupAthletes(race().athletes,division);
const viewRace=()=>({...race(),athletes:visibleAthletes()});
const athlete=()=>visibleAthletes().find(a=>a.id===athleteId)||visibleAthletes()[0];
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function save(){try{validateData(data);if(recoveryRaw)throw Error('旧数据备份待恢复');localStorage.setItem(KEY,JSON.stringify(data));storageError='';return true;}catch(e){storageError='保存失败：'+e.message;notify(storageError+'，请导出 JSON');return false;}}
function commit(message){save();render();if(!storageError)notify(message);}
function initials(a){return a.name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();}
const navItems=[['overview','grid','战况总览'],['splits','users','选手与计时'],['data','database','数据管理'],['help','help','计算说明']];
function navigatePage(next){page=next;render();window.scrollTo({top:0,left:0,behavior:'instant'});}
function openDataRecovery(){navigatePage('data');const button=$('#recover')||$('#export-json');button?.focus();button?.scrollIntoView({block:'center'});}
function storageNotice(){return storageError&&!storageNoticeDismissed?`<div class="storage-alert" role="alert"><div><strong>数据保存需要处理</strong><p>${esc(storageError)}</p></div><button id="open-recovery">${recoveryRaw?'备份并恢复':'查看保存状态'}</button><button id="dismiss-storage-notice" aria-label="关闭保存提醒">${icon('x')}</button></div>`:'';}
function render(){
  cancelAnimationFrame(playbackFrame);const focus=focusSelector(document.activeElement);chartObserver.disconnect();
  if(!divisions().includes(division))division=divisions()[0]||'open';
  const r=race(),a=athlete();if(a)athleteId=a.id;
  $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brandmark">${brandMark()}</div><div class="brand-text"><strong>ELITE<br>MARATHON</strong><small>ANALYTICS PLATFORM</small></div></div><div><div class="nav-label eyebrow">WORKSPACE</div><nav class="nav" aria-label="主导航">${navItems.map(([id,i,n])=>`<button data-page="${id}" class="${page===id?'active':''}" title="${n}" aria-label="${n}" ${page===id?'aria-current="page"':''}>${icon(i)}<span class="nav-text">${n}</span><span>${id==='splits'?r.athletes.length:''}</span></button>`).join('')}</nav></div><div class="sidebar-bottom"><div class="sidebar-footer"><span>EMA / VERSION 1.0</span><span>↗</span></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumbs">工作空间 <span style="margin-left:10px">/</span><b>${navItems.find(x=>x[0]===page)[2]}</b></div><div class="top-actions"><span class="save-status ${storageError?'error':''}" title="${esc(storageError)}">${storageError?'● 本地保存异常':'● 已在本地保存'}</span><button class="theme-toggle ghost" id="theme" aria-label="切换深浅主题" title="切换深浅主题">${icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')}</button></div></header><div class="content">${storageNotice()}<div class="page-heading"><div><div class="eyebrow" style="margin-bottom:10px">EVERY SECOND TELLS A STORY</div><h1>${navItems.find(x=>x[0]===page)[2]}</h1><p>${page==='overview'?'读懂每一段配速，追踪每一次领先。':'Elite Marathon Analytics · 42.195 公里的每一个细节'}</p></div><div class="heading-buttons"><button class="ghost" id="new-race">${icon('plus')}创建赛事</button><button class="primary" id="add-athlete">${icon('plus')}添加选手</button></div></div><div class="race-select-row"><select id="race-select" aria-label="选择赛事">${data.races.map(x=>`<option value="${esc(x.id)}" ${x.id===r.id?'selected':''}>${esc(x.name)} · ${esc(x.date)}</option>`).join('')}</select><div class="race-meta">${r.demo?'<span class="badge demo" title="选手与成绩均为虚构">模拟数据</span>':r.sources?.length?'<button class="badge source-badge" id="view-sources" title="查看官方完赛成绩与第三方分段来源">赛事资料 ↗</button>':''}<span>${esc(r.date)}</span><span>·</span><span>42.195 KM</span><button class="small ghost" id="edit-race" aria-label="编辑赛事">${icon('edit')}</button></div></div>${['overview','splits'].includes(page)&&divisions().length?`<div class="group-tabs" aria-label="赛事组别">${divisions().map(g=>`<button data-group="${g}" class="${g===division?'active':''}" aria-pressed="${g===division}">${GROUPS[g]}<span>${groupAthletes(r.athletes,g).length}</span></button>`).join('')}</div>`:''}${page==='overview'?overview():page==='splits'?splitsPage():page==='data'?dataPage():helpPage()}<footer class="bottom-note"><span>ELITE MARATHON ANALYTICS <span style="opacity:.4">/</span> 为比赛中的每一个决定提供依据</span><span>42.195 KM · EVERY SECOND COUNTS</span></footer></div></main></div>`;
  bindGlobal();if(page==='overview')bindOverview();if(page==='splits')bindSplits();if(page==='data')bindData();
  if($('#chart-region'))chartObserver.observe($('#chart-region'));saveView();restoreFocus(focus);if(focus&&document.activeElement===document.body){const heading=$('h1');heading.tabIndex=-1;heading.focus({preventScroll:true});}
  const status=$('#view-status');if(status)status.textContent=`${race().name}，${GROUPS[division]}，${label(POINTS[checkpoint])}，${athlete()?.name||'尚无选手'}`;
}
function overview(){
  const r=viewRace(),a=athlete(),d=POINTS[checkpoint],rows=standings(r.athletes,d),lead=rows[0],second=rows[1];
  const latest=a?metrics(a.splits,a.target).filter(s=>s.distance<=d).at(-1):null, leaders=leaderSummary(rows);
  return `<div class="stats"><div class="stat"><div class="stat-head">当前领先累计用时 ${icon('clock')}</div><div class="stat-value mono">${time(lead?.record.seconds)}</div><div class="stat-foot">${lead?esc(lead.athlete.name):'尚无计时数据'} <span>· ${label(d)}</span></div></div><div class="stat"><div class="stat-head">领先者平均配速 ${icon('bolt')}</div><div class="stat-value mono">${pace(lead?.record.average)}<small>/km</small></div><div class="stat-foot">起点至 ${label(d)} · 累计距离均速</div></div><div class="stat"><div class="stat-head">领先优势 ${icon('flag')}</div><div class="stat-value mono">${leaders.tied?'并列领先':second?pace(second.gap):'—'}<small>${leaders.tied?leaders.count+' 人':second?'领先第二名':''}</small></div><div class="stat-foot">${leaders.tied?esc(leaders.names.join(' · ')):second?esc(second.athlete.name):'至少需要两名选手通过此计时点'}</div></div><div class="stat"><div class="stat-head">${d===DISTANCE?'已完赛选手':'领先者预计完赛'} ${icon('target')}</div><div class="stat-value mono">${d===DISTANCE?rows.length+'<small>/ '+r.athletes.length+' 人</small>':time(lead?.record.projected)}</div><div class="stat-foot">${d===DISTANCE?'本组已有终点计时的选手':'基于累计平均配速 · 非预测模型'}</div></div></div><div class="workspace"><div class="left-stack"><section class="panel chart-panel"><div class="panel-header"><div><h2>${mode==='pace'?'配速走势':mode==='gap'?'选手间时间差':'领先优势走势'}</h2><p>${mode==='pace'?'分段配速 / MIN:SEC PER KM':mode==='gap'?`相对 ${esc(a?.name||'所选选手')} 的累计用时差`:'同一计时点第二名与第一名的累计用时差'}</p></div><div class="segmented" aria-label="图表类型">${[['pace','分段配速'],['gap','时间差'],['lead','领先优势']].map(([m,n])=>`<button data-mode="${m}" class="${mode===m?'active':''}" aria-pressed="${mode===m}">${n}</button>`).join('')}</div></div><div class="checkpoint"><div class="checkpoint-top"><span>计时点回看 <span class="muted">/ 拖动查看战况</span></span><strong>${label(d)} <span class="muted">· ${d} km</span></strong></div><input id="checkpoint" aria-label="回看计时点" aria-valuetext="${label(d)}" type="range" min="0" max="9" step="1" value="${checkpoint}"><div class="checkpoint-labels"><span>5K</span><span>半程</span><span>终点 · 42.195K</span></div></div><div id="chart-region">${chartMarkup()}</div></section><section class="panel"><div class="panel-header"><div><h2>当前排名 <span class="badge" style="margin-left:8px">${label(d)}</span></h2><p>仅比较当前计时点 · ${rows.length} / ${r.athletes.length} 位选手已有记录</p></div><button id="all-splits" class="small ghost">全部计时 ${icon('chart')}</button></div>${rows.length?`<div class="table-scroll"><table class="leaderboard"><thead><tr><th>排名</th><th>选手</th><th>累计用时</th><th>落后领先者</th><th>分段配速</th><th>变化 /km</th></tr></thead><tbody>${rows.map(({athlete:x,record:s,gap,rank})=>`<tr data-athlete="${esc(x.id)}" class="${x.id===athleteId?'selected':''}" tabindex="${x.id===(rows.find(row=>row.athlete.id===athleteId)?.athlete.id||rows[0]?.athlete.id)?0:-1}" aria-selected="${x.id===athleteId}" aria-label="查看 ${esc(x.name)}"><td class="rank mono ${rank===1?'leading':''}">${String(rank).padStart(2,'0')}</td><td><div class="runner-cell"><span class="swatch" style="background:${athleteColor(x.color)}"></span><div><div class="runner-name">${esc(x.name)}</div><div class="runner-sub">${esc(x.country)} ${x.bib ? `<span>· #${esc(x.bib)}</span>` : ''}</div></div></div></td><td class="mono">${time(s.seconds)}</td><td class="mono ${gap===0?'green':''}">${gap===0?'领先':delta(gap)}</td><td class="mono">${pace(s.segment)}</td><td class="mono ${s.change<0?'green':s.change>0?'red':''}">${delta(s.change)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">此计时点还没有数据。<br>选择更早的计时点，或录入新的累计用时。</div>`}</section></div><div class="right-stack"><section class="panel runner-detail">${a?`<div class="detail-top"><span class="eyebrow">ATHLETE FOCUS</span><span class="badge">选手详情</span></div><div style="display:flex;align-items:center;gap:12px;margin-top:20px"><div class="avatar detail-avatar" style="--athlete:${athleteColor(a.color)}">${esc(initials(a))}</div><div><h2 style="margin:0">${esc(a.name)}</h2><div class="detail-sub">${esc(a.country)}${a.bib ? ` · #${esc(a.bib)}` : ''}</div></div></div><div class="detail-number mono">${time(latest?.seconds)}</div><div class="detail-label">${latest?`最近已录入 · ${label(latest.distance)}`:'尚未录入计时'}${latest&&latest.distance!==d?'（早于当前回看点）':''}</div><div class="detail-grid"><div><span>分段配速 /km</span><strong class="mono">${pace(latest?.segment)}</strong></div><div><span>平均配速 /km</span><strong class="mono">${pace(latest?.average)}</strong></div><div><span>${latest?.distance===DISTANCE?'完赛成绩':'预计完赛'}</span><strong class="mono">${time(latest?.projected)}</strong></div><div><span>已录入计时点</span><strong class="mono">${a.splits.length}<span> / 10</span></strong></div></div><select id="focus-athlete" class="full" aria-label="选择分析选手">${r.athletes.map(x=>`<option value="${esc(x.id)}" ${x.id===a.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><button id="edit-focus" class="full">${icon('edit')}编辑选手与计时</button>`:`<div class="empty">添加选手，开始分析。</div>`}</section><section class="panel target-panel"><div class="target-heading"><h2>目标追踪</h2>${icon('target')}</div><div class="target-label">${a?esc(a.name):'选手'} · 目标完赛成绩</div><div class="target-time mono">${time(a?.target)}</div><div class="target-compare"><span class="muted">目标平均配速</span><span class="mono">${a?.target?pace(a.target/DISTANCE)+' /km':'未设置'}</span></div>${a?.target?`<div class="target-distance-label muted">已录入距离 · ${latest?label(latest.distance):'尚无记录'}</div><div class="target-track" aria-hidden="true"><div style="width:${latest?Math.min(100,latest.distance/DISTANCE*100):0}%"></div></div>`:''}<div class="target-compare"><span class="muted">${latest?label(latest.distance):'当前'}实际对比目标</span><strong class="mono ${latest?.targetGap<=0?'green':'red'}">${delta(latest?.targetGap)}</strong></div><p class="target-explainer" style="margin-top:12px">负值表示快于目标；正值表示落后。目标曲线按全程匀速计算。</p>${a?`<button id="edit-target" class="full small ghost">${icon('target')}设置目标成绩</button>`:''}</section></div></div>`;
}
function chartAthletes(){
 const all=visibleAthletes();if(chartScope==='all')return all;if(chartScope==='selected')return athlete()?[athlete()]:[];
 const ranked=[...all].sort((a,b)=>(a.splits.find(s=>s.distance===POINTS[checkpoint])?.seconds??Infinity)-(b.splits.find(s=>s.distance===POINTS[checkpoint])?.seconds??Infinity));
 const selected=athlete();return [selected,...ranked.filter(a=>a.id!==selected?.id)].filter(Boolean).slice(0,12);
}
function chartSeries(){
  const r=viewRace(),a=athlete();
  if(mode==='lead')return [{name:'领先优势',color:COLORS[0],values:POINTS.map(d=>{const rows=standings(r.athletes,d);return rows.length>1?rows[1].gap:null;})}];
  const ref=a?.splits||[];
  const series=chartAthletes().filter(x=>!hidden.has(x.id)).map(x=>({id:x.id,name:x.name,color:x.color,selected:x.id===a?.id,values:POINTS.map(d=>{
    const m=metrics(x.splits).find(s=>s.distance===d);if(!m)return null;
    if(mode==='pace')return m.segment;
    const reference=ref.find(s=>s.distance===d);return reference?m.seconds-reference.seconds:null;
  })}));
  if(mode==='pace'&&a?.target)series.push({name:`目标 · ${a.name}`,color:'target',values:POINTS.map(()=>a.target/DISTANCE),dash:true});
  return series;
}
function chartMarkup(){
  const series=chartSeries(),values=series.flatMap(s=>s.values).filter(Number.isFinite);
  const low=values.length?Math.min(...values):mode==='pace'?170:0,high=values.length?Math.max(...values):mode==='pace'?190:60;
  const {min,max,values:ticks}=niceTicks(low,high,mode);
  const width=Math.max(240,chartWidth||(($("#chart-region")?.clientWidth||650)-24)),mobile=width<640,rightEdge=width-25;
  const {height,plotHeight,labelY}=chartGeometry(width);
  const x=d=>55+(d-5)/(DISTANCE-5)*(width-80),y=v=>20+(max-v)/(max-min)*plotHeight;
  const format=v=>mode==='pace'?pace(v):delta(v);
  let svg=`<svg class="chart" style="height:${height}px" viewBox="0 0 ${width} ${height}" role="group" aria-label="${mode==='pace'?'分段配速趋势':mode==='gap'?'选手累计时间差':'领先优势'}，悬停或使用 Tab 查看计时点">`;
  svg+=`<defs><linearGradient id="ema-guide" x1="0" y1="0" x2="0" y2="1"><stop offset="0" style="stop-color:var(--spectrum-6)"/><stop offset=".5" style="stop-color:var(--spectrum-4)"/><stop offset="1" style="stop-color:var(--spectrum-1)"/></linearGradient></defs>`;
  for(const v of ticks){svg+=`<line class="gridline" x1="48" x2="${rightEdge}" y1="${y(v)}" y2="${y(v)}"/><text x="38" y="${y(v)+4}" text-anchor="end">${format(v)}</text>`;}
  if(mode!=='pace'&&min<0&&max>0)svg+=`<line x1="48" x2="${rightEdge}" y1="${y(0)}" y2="${y(0)}" stroke="var(--muted)" stroke-opacity=".4"/>`;
  svg+=`<line x1="${x(POINTS[checkpoint])}" x2="${x(POINTS[checkpoint])}" y1="15" y2="${height-35}" stroke="url(#ema-guide)" stroke-opacity=".65" stroke-dasharray="4 5"/>`;
  for(const s of series){let path='',active=false;for(let i=0;i<POINTS.length;i++){const v=s.values[i];if(!Number.isFinite(v)){active=false;continue;}path+=`${active?'L':'M'}${x(POINTS[i])},${y(v)} `;active=true;}
    const color=s.color==='target'?'var(--muted)':athleteColor(s.color);
    svg+=`<g class="series${s.selected?' selected-series':''}" style="color:${color}">`;
    svg+=`<path d="${path}" fill="none" stroke="currentColor" stroke-width="${s.dash?1.6:s.selected?3.6:1.8}" stroke-linecap="round" stroke-linejoin="round" ${s.dash?'stroke-dasharray="5 5"':''}/>`;
    if(!s.dash)s.values.forEach((v,i)=>{if(Number.isFinite(v))svg+=`<circle cx="${x(POINTS[i])}" cy="${y(v)}" r="${s.selected?4.2:2.8}" fill="var(--panel)" stroke="currentColor" stroke-width="1.8"/>`;});
    svg+=`</g>`;
  }
  POINTS.forEach((d,i)=>{const pos=x(d),left=i===0?35:(x(POINTS[i-1])+pos)/2,right=i===9?rightEdge+10:(x(POINTS[i+1])+pos)/2;svg+=`<text x="${pos}" y="${labelY(i)}" text-anchor="middle">${d===21.0975?'HM':d===DISTANCE?(mobile?'FIN':'42.195'):d+'K'}</text><rect class="tick-hit" data-tick="${i}" x="${left}" y="12" width="${right-left}" height="${height-45}" tabindex="${i===checkpoint?0:-1}" role="button" aria-label="查看 ${label(d)}"/>`;});
  svg+='</svg>';
  return `${mode!=='lead'?`<div class="chart-controls"><label for="chart-scope">图表选手</label><select id="chart-scope" aria-label="图表选手范围">${[['top','领先12人（含当前选手）'],['selected','仅当前选手'],['all','全部选手']].map(([v,n])=>`<option value="${v}" ${chartScope===v?'selected':''}>${n}</option>`).join('')}</select><span class="muted">粗线 / 大圆点：当前选手</span></div>`:''}<div class="chart-wrap">${svg}<div class="chart-tooltip" id="chart-tooltip">${tooltip(checkpoint)}</div></div><div class="legend">${mode!=='lead'?chartAthletes().map(a=>`<label title="${esc(a.name)}"><input type="checkbox" data-visible="${esc(a.id)}" ${hidden.has(a.id)?'':'checked'} style="accent-color:${athleteColor(a.color)}"><span class="swatch" style="background:${athleteColor(a.color)}"></span>${esc(a.name)}</label>`).join(''):'<span class="muted" style="font-size:10px">● 领先者对第二名的优势（秒）</span>'}${mode==='pace'&&athlete()?.target?'<span class="muted" style="font-size:10px">┄ 所选选手目标配速</span>':''}</div><div class="chart-note">${mode==='pace'?'配速越低越快 · 缺失计时点不插值；跨点区间取相邻已录入记录的均速。':mode==='gap'?'正值表示慢于所选选手，负值表示快于所选选手；仅比较双方均有记录的计时点。':'每个计时点独立取最快两人，领先者可能变化；不足两人时不显示。'} 悬停 / Tab 查看，点击计时点回看。${visibleAthletes().some(a=>a.splitSourceUrl)?'<span class="source-context">第三方中途记录待核验 · 同秒记录不能确认真实间距或战术动作。<button class="inline-source" id="chart-sources">查看来源</button></span>':''}</div>`;
}
function tooltip(i){return `<strong>${label(POINTS[i])}</strong>`+chartSeries().map(s=>`<span><i class="swatch" style="background:${s.color==='target'?'var(--muted)':athleteColor(s.color)}"></i> ${esc(s.name)} <strong class="mono">${Number.isFinite(s.values[i])?(mode==='pace'?pace(s.values[i]):delta(s.values[i])):'—'}</strong></span>`).join('');}
function bindChart(){
 if($('#chart-sources'))$('#chart-sources').onclick=()=>{navigatePage('data');$('.data-card h2')?.scrollIntoView({block:'start'});};
 if($('#chart-scope'))$('#chart-scope').onchange=e=>{chartScope=e.target.value;hidden.clear();refreshChart();};
 document.querySelectorAll('[data-tick]').forEach(el=>{
  const show=()=>{$('#chart-tooltip').innerHTML=tooltip(Number(el.dataset.tick));};el.onmouseenter=show;el.onfocus=show;
  el.onclick=()=>{checkpoint=Number(el.dataset.tick);render();};
  el.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const index=e.key==='Home'?0:e.key==='End'?9:Math.max(0,Math.min(9,Number(el.dataset.tick)+(e.key==='ArrowLeft'?-1:1)));document.querySelector('[data-tick="'+index+'"]').focus();}if(e.key==='Enter'||e.key===' '){e.preventDefault();checkpoint=Number(el.dataset.tick);render();}};
 });
 document.querySelectorAll('[data-visible]').forEach(el=>el.onchange=()=>{el.checked?hidden.delete(el.dataset.visible):hidden.add(el.dataset.visible);refreshChart();});
}
function bindGlobal(){
  document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>navigatePage(el.dataset.page));
  if($('#open-recovery'))$('#open-recovery').onclick=openDataRecovery;
  if($('#dismiss-storage-notice'))$('#dismiss-storage-notice').onclick=()=>{storageNoticeDismissed=true;render();$('#theme').focus();};
  $('#theme').onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('elite-marathon.theme',document.documentElement.dataset.theme);}catch{}syncThemeColor();render();};
  $('#race-select').onchange=e=>{raceId=e.target.value;athleteId=race().athletes[0]?.id;hidden.clear();render();};
  document.querySelectorAll('[data-group]').forEach(el=>el.onclick=()=>{division=el.dataset.group;athleteId=visibleAthletes()[0]?.id;hidden.clear();render();});
  if($('#view-sources'))$('#view-sources').onclick=()=>{page='data';render();$('.data-card h2')?.scrollIntoView({block:'start'});};
  $('#new-race').onclick=()=>raceModal();$('#edit-race').onclick=()=>raceModal(race());$('#add-athlete').onclick=()=>athleteModal();
}
function bindOverview(){
  document.querySelectorAll('[data-mode]').forEach(el=>el.onclick=()=>{mode=el.dataset.mode;render();});
  $('#checkpoint').oninput=e=>{checkpoint=Number(e.target.value);cancelAnimationFrame(playbackFrame);playbackFrame=requestAnimationFrame(updatePlayback);};
  document.querySelectorAll('[data-athlete]').forEach(el=>{el.onclick=()=>{athleteId=el.dataset.athlete;render();};el.onkeydown=e=>{if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const rows=[...document.querySelectorAll('[data-athlete]')],index=rows.indexOf(el),next=e.key==='Home'?0:e.key==='End'?rows.length-1:Math.max(0,Math.min(rows.length-1,index+(e.key==='ArrowUp'?-1:1)));rows.forEach(r=>r.tabIndex=-1);rows[next].tabIndex=0;rows[next].focus();}if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click();}};});
  if($('#focus-athlete'))$('#focus-athlete').onchange=e=>{athleteId=e.target.value;render();};
  if($('#edit-focus'))$('#edit-focus').onclick=()=>athleteModal(athlete());
  if($('#edit-target'))$('#edit-target').onclick=()=>{athleteModal(athlete());$('#target').focus();};
  $('#all-splits').onclick=()=>navigatePage('splits');bindChart();
}
function splitsPage(){const r=viewRace();return `<section class="panel"><div class="panel-header"><div><h2>累计计时记录 <span class="badge">${r.athletes.length} 位选手</span></h2><p>点击任意用时编辑 · 留空可删除计时点 · 全程 42.195 km，半程 21.0975 km</p></div></div>${r.athletes.length?`<div class="table-scroll"><table class="leaderboard split-table"><thead><tr><th>选手</th>${POINTS.map(d=>`<th>${label(d)}<div style="font-size:9px;margin-top:4px">${d} km</div></th>`).join('')}<th>目标成绩</th><th></th></tr></thead><tbody>${r.athletes.map(a=>`<tr><td><div class="runner-cell"><span class="swatch" style="background:${athleteColor(a.color)}"></span><div><div class="runner-name">${esc(a.name)}</div><div class="runner-sub">${esc(a.country)}${a.bib ? ` · #${esc(a.bib)}` : ''}</div></div></div></td>${POINTS.map(d=>`<td><button class="mono" data-edit="${esc(a.id)}" data-distance="${d}" aria-label="编辑 ${esc(a.name)} ${label(d)}">${time(a.splits.find(s=>s.distance===d)?.seconds)}</button></td>`).join('')}<td class="mono">${time(a.target)}</td><td><button data-edit="${esc(a.id)}" aria-label="编辑 ${esc(a.name)}">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">还没有选手。点击右上角“添加选手”开始录入。</div>'}</section><div class="panel help-copy" style="margin-top:20px"><h2>累计计时，而非单段用时</h2><p>例如 5K 输入 0:14:40，10K 输入 0:29:16。系统自动计算 5–10K 用时 14:36，配速 2:55/km。中间漏录时，配速按照相邻已录入计时点之间的实际距离计算。编辑窗口提供即时试算，保存后更新全部图表。</p></div>`;}
function bindSplits(){document.querySelectorAll('[data-edit]').forEach(el=>el.onclick=()=>{athleteModal(race().athletes.find(a=>a.id===el.dataset.edit));if(el.dataset.distance)document.querySelector(`[name="split-${el.dataset.distance}"]`).focus();});}
function dataPage(){return `<div class="data-grid">${sourceCard()}<section class="panel data-card"><h2>导出工作空间</h2><p>保存所有赛事、选手、目标成绩及累计计时。JSON 适合完整备份；CSV 适合表格编辑，时间单位为秒，距离单位为公里。</p><div class="button-row"><button id="export-json" class="primary">${icon('arrow')}导出 JSON</button><button id="export-csv">${icon('arrow')}导出 CSV</button></div></section><section class="panel data-card"><h2>导入赛事数据</h2><p>选择本平台格式的 JSON 或 CSV（最大 5 MB）。校验通过后以新赛事副本追加，不覆盖现有数据。CSV 可先导出作为模板。</p><label for="import-file">选择 JSON / CSV 文件</label><input class="file-input" id="import-file" type="file" accept=".json,.csv,application/json,text/csv"><p id="import-status" role="status" style="margin:0"></p></section><section class="panel data-card"><h2>模拟数据与演示</h2><p>载入一场包含 5 位虚构选手、截至 35K 的模拟赛事。每场模拟赛事都带有明显标识，导出时保留 demo 字段。</p><button id="load-demo">${icon('plus')}添加模拟赛事副本</button></section><section class="panel data-card"><h2>存储状态</h2><p>${storageError?esc(storageError):'自动保存已启用。数据仅保存在当前浏览器的此站点存储中，不会上传到服务器。'}<br>${data.races.length} 场赛事 · ${data.races.reduce((n,r)=>n+r.athletes.length,0)} 位选手<br>更换浏览器或清除站点数据前，请导出 JSON 备份。</p>${recoveryRaw?'<button id="recover">下载旧数据并恢复保存</button>':'<span class="badge">浏览器本地存储</span>'}</section></div>`;}
function sourceCard(){
  const sources=(race().sources||[]).filter(s=>typeof s?.url==='string'&&/^https:\/\//.test(s.url));
  return sources.length?`<section class="panel data-card"><h2>赛事资料来源</h2><p>${esc(race().sourceNote||'')}</p>${race().splitSourceNotes?.length?`<details><summary>分段来源差异说明</summary>${race().splitSourceNotes.map(n=>`<p>${esc(n)}</p>`).join('')}</details>`:''}<details class="source-links"><summary>查看 ${sources.length} 个资料来源</summary>${sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title||s.url)}</a>`).join('')}</details></section>`:'';
}
function download(content,type,name){const url=URL.createObjectURL(new Blob([content],{type}));const link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function bindData(){
  $('#export-json').onclick=()=>download(JSON.stringify(data,null,2),'application/json','elite-marathon-backup.json');
  $('#export-csv').onclick=()=>download(toCSV(data),'text/csv;charset=utf-8','elite-marathon-data.csv');
  $('#load-demo').onclick=()=>{if(data.races.length>=100){notify('最多可保存 100 场赛事，请先导出并整理');return;}const r=demoRace();data.races.push(r);raceId=r.id;athleteId=r.athletes[0].id;commit('已添加明确标注的模拟赛事');};
  if($('#recover'))$('#recover').onclick=()=>{
  try{validateData(data);localStorage.setItem('elite-marathon.corrupt-backup',recoveryRaw);download(recoveryRaw,'application/json','elite-marathon-recovery.json');localStorage.setItem(KEY,JSON.stringify(data));recoveryRaw=null;storageError='';render();notify('旧数据已备份，已恢复保存');}catch(err){storageError='恢复失败：'+err.message;render();notify(storageError);}
 };
  $('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('文件大于 5 MB');if(!/\.(json|csv)$/i.test(file.name))throw Error('请选择 JSON 或 CSV');const text=await file.text();const incoming=file.name.toLowerCase().endsWith('.csv')?fromCSV(text):validateData(JSON.parse(text));if(data.races.length+incoming.races.length>100)throw Error('导入后赛事数量超过 100');importModal(incoming,file.name);}catch(err){$('#import-status').textContent='导入失败：'+err.message;$('#import-status').className='red';}e.target.value='';};
}
function helpPage(){return `<section class="panel help-copy"><h2>计算规则</h2><p>全程 <code>42.195 km</code>；半程 <code>21.0975 km</code>。累计时间用秒保存，所有运算使用完整精度，仅在界面显示时四舍五入到秒。</p><h2>分段配速与变化</h2><p>分段配速 =（当前累计秒数 − 上一个已录入点累计秒数）÷（当前距离 − 上一个已录入点距离），单位为秒/公里。第一段从起点 0 km、0 秒开始。变化 = 当前分段配速 − 上一分段配速；负值表示加速。若漏录计时点，使用跨越该点的整体均速，不猜测中间成绩。</p><h2>平均配速与预计完赛</h2><p>平均配速 = 累计秒数 ÷ 当前公里数。预计完赛 = 平均配速 × 42.195。这是均速外推，不考虑体能、赛道、天气。录入终点后显示实际成绩。</p><h2>排名、时间差与领先优势</h2><p>仅比较同一距离已有记录的选手，不将不同计时点混在一起排名。相同累计成绩并列排名。时间差曲线以右侧所选选手为基准；缺少共同计时点时留空。领先优势 = 第二快累计用时 − 最快累计用时，并列领先时为 0。</p><h2>目标曲线</h2><p>目标配速 = 目标完赛秒数 ÷ 42.195。某计时点的目标累计时间 = 目标完赛秒数 × 该点距离 ÷ 42.195。实际差距 = 实际累计时间 − 目标累计时间。</p><h2>输入校验与数据</h2><p>输入 H:MM:SS 或 MM:SS。累计时间必须严格递增，且在 0–48 小时内；允许暂时缺少任意计时点。编辑时留空可删除单个计时点。导入先完整校验，再创建副本；失败时不改变现有工作空间。JSON 使用 version: 1；CSV 单位固定为公里和秒，支持引号、逗号及换行。</p><h2>演示与实时更新的边界</h2><p>标有“模拟数据”的赛事及选手为虚构，标识会保留在导出数据中。伦敦赛事的完赛成绩来自官方结果，中途分段主要来自第三方公开记录，来源及差异见数据管理。“即时”指每次保存录入后立即重新计算；未连接实时计时服务。</p></section>`;}
function openModal(title,body,footer){if(!$('#modal').open&&!document.activeElement?.closest('dialog'))modalOpener=focusSelector(document.activeElement);document.querySelector('#modal').oncancel=null;$('#modal').removeAttribute('aria-describedby');$('#modal').innerHTML=`<div class="modal-header"><h2 id="modal-title">${title}</h2><button type="button" data-close aria-label="关闭">${icon('x')}</button></div>${body}${footer||''}`;$('#modal').setAttribute('aria-labelledby','modal-title');$('#modal').showModal();$('#modal').onclose=()=>queueMicrotask(()=>{if(!$('#modal').open){restoreFocus(modalOpener);if(document.activeElement===document.body)$('#new-race')?.focus({preventScroll:true});}});($('#modal').querySelector('input:not([disabled]),select')||$('#modal').querySelector('button.primary,button[data-close]'))?.focus();$('#modal').querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#modal').close());}
function raceModal(existing){
  openModal(existing?'编辑赛事':'创建赛事',`<form id="race-form"><div class="modal-body"><div class="form-grid"><label class="form-field wide">赛事名称<input name="name" required maxlength="100" value="${esc(existing?.name||'')}" placeholder="例如：2026 TCS London Marathon"></label><div class="form-field date-control"><label for="race-date">赛事日期</label><div class="date-input-wrap"><input id="race-date" name="date" type="text" required pattern="[0-9]{4}-[0-9]{2}-[0-9]{2}" maxlength="10" placeholder="YYYY-MM-DD" autocomplete="off" value="${esc(existing?.date||localDate())}"><button type="button" id="date-toggle" aria-label="打开日历" aria-expanded="false" aria-controls="date-calendar"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 4h14v17H5z M8 2v5 M16 2v5 M5 10h14"/></svg></button></div><div id="date-calendar" class="calendar" role="group" aria-label="选择赛事日期" hidden></div></div><div class="form-field"><label>比赛距离</label><input value="42.195 km" disabled style="width:100%;margin-top:8px"></div></div><label class="checkbox-label"><input name="demo" type="checkbox" ${existing?.demo?'checked':''}>这是模拟赛事（虚构数据请勾选）</label><p class="error-message" id="form-error" role="alert"></p></div><div class="modal-footer">${existing?'<button type="button" class="danger" id="delete-race">删除赛事</button>':''}<div class="right"><button type="button" data-close>取消</button><button class="primary" type="submit">${existing?'保存修改':'创建赛事'}</button></div></div></form>`);
  mountCalendar($('#race-form'));
  $('#race-form').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),name=f.get('name').trim();if(!name)throw Error('请填写赛事名称');const r={...existing,id:existing?.id||uid(),name,date:f.get('date'),demo:f.has('demo'),athletes:existing?.athletes||[]};const next=structuredClone(data);if(existing)next.races[next.races.findIndex(x=>x.id===existing.id)]=r;else next.races.push(r);validateData(next);data=next;raceId=r.id;athleteId=r.athletes[0]?.id;$('#modal').close();commit('赛事已保存');}catch(err){$('#form-error').textContent=err.message;}};
  if(existing)$('#delete-race').onclick=()=>confirmDelete('删除此赛事？','赛事及选手记录会从当前工作空间移除。删除后可通过提示按钮撤销。',()=>{const previous=structuredClone(data);data.races=data.races.filter(r=>r.id!==existing.id);if(!data.races.length)data.races=[{id:uid(),name:'未命名赛事',date:localDate(),demo:false,athletes:[]}];raceId=data.races[0].id;commit('赛事已删除');undoModal(previous);});
}
function athleteModal(existing){
  openModal(existing?'编辑选手与累计计时':'添加精英选手',`<form id="athlete-form" novalidate><div class="modal-body"><div class="form-grid"><label class="form-field wide">选手姓名<input name="name" required maxlength="80" value="${esc(existing?.name||'')}" placeholder="选手姓名"></label><label class="form-field">号码布<input name="bib" maxlength="20" value="${esc(existing?existing.bib:String(race().athletes.length+1).padStart(3,'0'))}"></label><label class="form-field">国家 / 地区<input name="country" maxlength="20" value="${esc(existing?.country||'')}" placeholder="例如 CHN"></label><label class="form-field wide">组别<select name="group">${Object.entries(GROUPS).map(([g,n])=>`<option value="${g}" ${g===(existing?.group||division)?'selected':''}>${n}</option>`).join('')}</select></label><label class="form-field">目标完赛成绩（可留空）<input id="target" name="target" value="${existing?.target?time(existing.target):''}" placeholder="2:03:00" inputmode="text"></label><label class="form-field">图表颜色<input type="color" name="color" value="${existing?.color||COLORS[race().athletes.length%COLORS.length]}" style="height:42px;padding:6px"></label></div><p class="form-hint" id="input-help">输入从起点起算的累计用时，格式 H:MM:SS 或 MM:SS。<br>允许缺失计时点；留空会删除该点。距离递增时，用时必须严格递增。</p><div class="live-calc" id="live-calc" aria-live="polite"></div><div class="split-inputs">${POINTS.map(d=>`<div class="split-input"><label for="s-${d}"><span>${label(d)}</span><span>${d} km</span></label><input id="s-${d}" name="split-${d}" data-split="${d}" placeholder="H:MM:SS" value="${time(existing?.splits.find(s=>s.distance===d)?.seconds).replace('—','')}" autocomplete="off"></div>`).join('')}</div><div class="error-message" id="form-error" role="alert"></div></div><div class="modal-footer">${existing?'<button type="button" class="danger" id="delete-athlete">删除选手</button>':''}<div class="right"><button type="button" data-close>取消</button><button class="primary" type="submit">保存并重新计算</button></div></div></form>`);
  $('#modal').setAttribute('aria-describedby','input-help');
  const clearErrors=()=>{$('#athlete-form').querySelectorAll('[aria-invalid]').forEach(el=>{el.removeAttribute('aria-invalid');el.removeAttribute('aria-describedby');});$('#athlete-form').querySelectorAll('.field-error').forEach(el=>el.remove());};
  const fieldError=(field,message)=>{const input=$('#athlete-form').elements.namedItem(field);input.setAttribute('aria-invalid','true');const hint=document.createElement('span');hint.className='field-error';hint.id='error-'+field;hint.textContent=message;input.insertAdjacentElement('afterend',hint);input.setAttribute('aria-describedby',hint.id);return Object.assign(Error(message),{field});};
  const read=(submitting=false)=>{
   clearErrors();const f=new FormData($('#athlete-form'));if(submitting&&!f.get('name').trim())throw fieldError('name','请填写选手姓名');
   const splits=[];let previous=0;
   for(const distance of POINTS){const field='split-'+distance,value=f.get(field).trim();if(!value)continue;let seconds;try{seconds=parseTime(value);}catch(err){throw fieldError(field,label(distance)+'：'+err.message);}if(seconds<=previous)throw fieldError(field,label(distance)+' 累计用时必须大于前一计时点');splits.push({distance,seconds});previous=seconds;}
   let target=null;if(f.get('target').trim()){try{target=parseTime(f.get('target'));}catch(err){throw fieldError('target',err.message);}}
   return {f,splits,target,result:metrics(splits,target)};
  };
  const recalc=()=>{try{const {result}=read(),focused=Number(document.activeElement?.dataset.split),m=result.find(s=>s.distance===focused)||result.at(-1);$('#form-error').textContent='';$('#live-calc').innerHTML=m?label(m.distance)+' · 分段 <strong class="mono">'+pace(m.segment)+'/km</strong> · 平均 <strong class="mono">'+pace(m.average)+'/km</strong><br>'+(m.distance===DISTANCE?'完赛':'预计完赛')+' <strong class="mono">'+time(m.projected)+'</strong> · 目标差距 <strong class="mono">'+delta(m.targetGap)+'</strong>':'填写任一计时点，即可查看即时试算。';}catch(err){$('#form-error').textContent=err.message;$('#live-calc').textContent=err.message;}};
  $('#athlete-form').oninput=recalc;$('#athlete-form').onfocusin=e=>{if(e.target.matches('[data-split]'))recalc();};recalc();
  $('#athlete-form').onsubmit=e=>{e.preventDefault();try{const {f,splits,target}=read(true);const name=f.get('name').trim();const a={...existing,id:existing?.id||uid(),name,group:f.get('group'),bib:f.get('bib').trim(),country:f.get('country').trim(),color:f.get('color'),target,splits};const next=structuredClone(data),r=next.races.find(r=>r.id===raceId);if(existing)r.athletes[r.athletes.findIndex(x=>x.id===existing.id)]=a;else r.athletes.push(a);validateData(next);data=next;division=a.group;athleteId=a.id;$('#modal').close();commit('选手已保存，所有分析已更新');}catch(err){$('#form-error').textContent=err.message;const input=$('#athlete-form').elements.namedItem(err.field||'name');input?.focus();input?.scrollIntoView({block:'center'});}};
  if(existing)$('#delete-athlete').onclick=()=>confirmDelete('删除此选手？',`将移除 ${esc(existing.name)} 的所有计时记录。删除后可撤销。`,()=>{const previous=structuredClone(data);race().athletes=race().athletes.filter(a=>a.id!==existing.id);athleteId=race().athletes[0]?.id;commit('选手已删除');undoModal(previous);});
}
function confirmDelete(title,copy,action){$('#modal').close();openModal(title,`<div class="modal-body"><p class="form-hint">${copy}</p></div>`,`<div class="modal-footer"><div class="right"><button data-close>取消</button><button class="danger" id="confirm-delete">确认删除</button></div></div>`);$('#confirm-delete').onclick=()=>{$('#modal').close();action();};}
function undoModal(previous){openModal('已删除',`<div class="modal-body"><p class="form-hint">可以立即撤销本次删除；关闭此窗口后，继续使用当前数据。</p></div>`,`<div class="modal-footer"><div class="right"><button id="undo" class="primary">撤销删除</button><button data-close>完成</button></div></div>`);$('#undo').onclick=()=>{data=previous;raceId=data.races[0].id;$('#modal').close();commit('已恢复删除前的数据');};}
function importModal(incoming,name){openModal('确认导入',`<div class="modal-body"><div class="import-summary">${esc(name)}<br><strong>${incoming.races.length}</strong> 场赛事 · <strong>${incoming.races.reduce((n,r)=>n+r.athletes.length,0)}</strong> 位选手<br>校验通过。导入为新副本，保留现有数据和模拟标识。</div></div>`,`<div class="modal-footer"><div class="right"><button data-close>取消</button><button class="primary" id="confirm-import">追加导入</button></div></div>`);$('#confirm-import').onclick=()=>{const copies=structuredClone(incoming.races).map(r=>({...r,id:uid(),athletes:r.athletes.map(a=>({...a,id:uid()}))}));data.races.push(...copies);raceId=copies[0].id;athleteId=copies[0].athletes[0]?.id;$('#modal').close();commit('已导入 '+copies.length+' 场赛事');};}

if(!storageError)save();render();
